Subroutine ChargeWithVat(total As Integer By Reference)
  total <- total + total * 18 Div 100;
  total <- total - total Div 10;
  Write "Total: ", total;
EndSubroutine

Algorithm Till
  Define purchase As Integer;
  Read purchase;
  ChargeWithVat(purchase);
EndAlgorithm

